const cmp=(id,title,kind,cases)=>({id,title,kind,type:'compare',cases});const seq=(id,title,kind,route,labels,why)=>({id,title,kind,type:'sequence',route,labels,why});
export function cultureCounts(antibiotic,stage){if(!['yes','no'].includes(antibiotic)||![0,1,2].includes(stage))throw new RangeError('Use a stated treatment and stage0–2.');let susceptible=antibiotic==='yes'&&stage>=1?0:16,resistant=4;if(stage===2){susceptible*=2;resistant*=2;}return{susceptible,resistant,total:susceptible+resistant,percent:100*resistant/(susceptible+resistant)};}
export function berryOutput(water,pollinators){if(!['wet','dry'].includes(water)||!['yes','no'].includes(pollinators))throw new RangeError('Choose both model inputs.');return(water==='wet'?12:6)*(pollinators==='yes'?1:1/3);}
export const webCases=['wet:yes','wet:no','dry:yes','dry:no'];
