export const tasksForBound=k=>boundTasks[k];export const validBound=(c,a)=>a!==''&&a!==null&&a!==undefined&&Number(a)===c[3];export const advanceBound=(r,n,v)=>Number.isInteger(n)&&n>=0&&n<r.length&&r[n]===v?n+1:n;export const numericBound=(v,a)=>v!==''&&v!==null&&v!==undefined&&Number.isFinite(Number(v))&&Math.abs(Number(v)-a)<.001;
